"""Write voice/index.js (window.VOICE_PACK = {spoken text: clip URL}) from voice/lines.json.

Run after adding clips: python tools/build_voice_index.py
"""
import json
from pathlib import Path

VDIR = Path(__file__).resolve().parent.parent / "voice"
lines = json.loads((VDIR / "lines.json").read_text(encoding="utf-8"))
missing = [t for t, f in lines.items() if not (VDIR / f).is_file()]
if missing:
    raise SystemExit(f"missing clip files for: {missing[:5]}")
pack = {t: "voice/" + f for t, f in sorted(lines.items())}
(VDIR / "index.js").write_text(
    "// Generated by tools/build_voice_index.py from voice/lines.json. Do not edit by hand.\n"
    "window.VOICE_PACK = " + json.dumps(pack, ensure_ascii=False, indent=0) + ";\n",
    encoding="utf-8")
print("clips:", len(pack))
